63	 * gives: finding count, file count and last build are all rolled up per PAGE
64	 * from other tables, so offering "sort by findings" would sort 25 arbitrary
65	 * rows and look like it had sorted the registry. The "Needs review" view is the
66	 * honest version of that request — it filters in the database instead.
67	 */
68	const SORTS: Record<SortKey, { label: string; orderBy: Prisma.ProjectOrderByWithRelationInput }> = {
69	  recent: { label: "Newest publish", orderBy: { publishedAt: "desc" } },
70	  oldest: { label: "Oldest publish", orderBy: { publishedAt: "asc" } },
71	  updated: { label: "Recently changed", orderBy: { updatedAt: "desc" } },
72	  slug: { label: "Slug", orderBy: { slug: "asc" } },
73	};
